onTextChanged:
{{
  (async () => {
    const documento = String(
      inpCpCedulaConductor.text || ""
    ).trim();

    if (documento.length < 5) {
      await storeValue(
        "cp_ui_conductor_estado_operativo",
        null
      );

      return;
    }

    /*
     * Limpia el resultado anterior para evitar mostrar
     * información de otro conductor mientras consulta.
     */
    await storeValue(
      "cp_ui_conductor_estado_operativo",
      null
    );

    const resultado =
      await qCpBuscarConductorPorDocumento.run();

    /*
     * Evita que una consulta anterior sobrescriba el resultado
     * si el usuario continuó escribiendo.
     */
    const documentoActual = String(
      inpCpCedulaConductor.text || ""
    ).trim();

    if (documentoActual !== documento) {
      return;
    }

    await storeValue(
      "cp_ui_conductor_estado_operativo",
      resultado?.[0] || null
    );
  })()
}}
